/* MIT. Exercise actual class cast validation, costs, channel completion and fields. */
#include <assert.h>
#include "combat.h"
#include "developer.h"
static int clear(void*w,float x,float y,float nx,float ny){(void)w;(void)x;(void)y;return nx>=8&&ny>=8&&nx<3192&&ny<3192;}
static int water(void*w,float x,float y,float nx,float ny){(void)w;(void)x;(void)y;(void)nx;(void)ny;return 1;}
static void prepare(Combat*g,unsigned job){combat_init(g,1500,1500,clear,NULL);dev_class_preset(g,job);memset(g->mobs,0,sizeof(g->mobs));g->canAim=clear;g->inWater=water;assert(dev_spawn(g,0,3));g->mobs[MOB_COUNT-1].x=g->x+10;g->mobs[MOB_COUNT-1].y=g->y;g->mobs[MOB_COUNT-1].hp=g->mobs[MOB_COUNT-1].testMaxHP=1000000;g->target=MOB_COUNT-1;g->sightLeft=10;g->hitStun=0;g->time=1;}
int main(void){Combat g;for(int id=69;id<89;id++){unsigned job=id<73?7:8;prepare(&g,job);int rank=skill_rank(&g,id);assert(rank>0);if(skill_passive(id))continue;int before=g.sp,cost=skill_cost(&g,id),hp=g.mobs[MOB_COUNT-1].hp;assert(before>=cost);if(!skill_cast(&g,id,g.x+10,g.y)){fprintf(stderr,"failed cast id%d: %s\n",id,g.log);abort();}for(int n=0;combat_casting(&g)&&n<1000;n++)combat_tick(&g,.05f,0,0);assert(!combat_casting(&g));if(id==76)for(int n=0;n<35;n++)combat_tick(&g,.05f,0,0);if(g.sp>before-cost){fprintf(stderr,"SP id%d: before%d cost%d after%d log:%s\n",id,before,cost,g.sp,g.log);abort();}if(id==69)assert(g.quickenLeft>0);if(id==70)assert(g.counterLeft>0);if(id==84)assert(g.sightblasterLeft>0);if(id==87)assert(g.magicAmpLeft>0);if(id==71||id==72||id==74||id==76||id==78||id==79||id==81||id==86||id==88)assert(g.mobs[MOB_COUNT-1].hp<hp);if(id==73||id==75||id==77||id==80||id==82){int active=0;for(int f=0;f<COMBAT_FIELDS;f++)active+=g.fields[f].remaining>0;assert(active);}}
prepare(&g,7);g.equipment&=~32u;int sp=g.sp;assert(!skill_cast(&g,69,g.x,g.y)&&g.sp==sp);prepare(&g,8);g.inWater=NULL;sp=g.sp;assert(!skill_cast(&g,78,g.x,g.y)&&g.sp==sp);prepare(&g,8);g.sightLeft=0;sp=g.sp;assert(!skill_cast(&g,74,g.x,g.y)&&g.sp==sp);
prepare(&g,8);sp=g.sp;assert(skill_cast(&g,75,g.x+10,g.y));assert(combat_casting(&g)&&g.sp==sp);combat_interrupt_cast(&g);assert(!combat_casting(&g)&&g.sp==sp);
prepare(&g,7);g.autoBerserk=1;g.hp=g.maxhp/8;assert(combat_berserk_active(&g));assert(class_count(&g)>4);prepare(&g,8);assert(class_count(&g)>20);assert(skill_rank(&g,4)==5);puts("PASS43 all19 new active second-job skills: source cost/rank cast completion, damage/buffs/field creation, inherited first-job access, sword/Sight/water resource gates and interrupted Meteor preserves SP.");}
